#' @title Add BANKSY clusters to Xenium object
#'
#' @description
#' Adds BANKSY-derived spatial cluster to
#' the metadata of a Xenium object.
#'
#' Cluster assignments generated by
#' compute_spatial_clusters() are transferred from a
#' BANKSY object to the original Xenium object for
#' downstream visualisation and analysis.
#'
#' @param xenium.obj Xenium object
#' @param BANKSY.obj Seurat object generated by
#' compute_spatial_clusters()
#' @param resolution Clustering resolution used during
#' compute_spatial_clusters()
#' @param metadata_name Name of the metadata column used
#' to store cluster assignments
#'
#' @returns Xenium object with BANKSY-derived spatial
#' clusters added to the metadata.
#'
#' @examples
#' \dontrun{
#' # Add arm clusters of desired lambda and resolution back to main Xenium object
#'xenium.obj <- add_banksy_clusters(xenium.obj,
#'                                  BANKSY.obj,
#'                                  resolution = 0.1)}
#'
#' @export
add_banksy_clusters <- function(
    xenium.obj,
    BANKSY.obj,
    resolution = 0.1,
    metadata_name = "banksy_clusters"
) {

  cluster_col <- paste0(
    "BANKSY_snn_res.",
    resolution
  )

  if (!cluster_col %in% colnames(BANKSY.obj@meta.data)) {
    stop(
      paste(
        "Cluster column not found:",
        cluster_col
      )
    )
  }

  # Check cell names match
  if (!identical(
    colnames(BANKSY.obj),
    colnames(xenium.obj)
  )) {

    stop(
      "Cell names or order differ between BANKSY.obj and xenium.obj"
    )

  }
  banksy_metadata <- data.frame(
    cluster = BANKSY.obj@meta.data[[cluster_col]]
  )

  rownames(banksy_metadata) <- colnames(BANKSY.obj)

  colnames(banksy_metadata) <- metadata_name

  xenium.obj <- Seurat::AddMetaData(
    xenium.obj,
    metadata = banksy_metadata
  )

  return(xenium.obj)
}
